-- ============================================================================
-- DEV/DEMO SEED — Dwarka, New Delhi. GENERATED by db/gen_dwarka_seed.py.
-- MAP model: JUNCTIONS are the nodes (cameras table); links are junction-to-
-- junction (each junction to every 1-edge road neighbour). The real per-
-- approach cameras live behind the scenes in approach_cameras (one per road
-- arriving at a junction) — sightings are aggregated up to the junction.
-- Re-runnable; TRUNCATEs the network — STOP the pipeline workers first.
-- ============================================================================
BEGIN;
CREATE TABLE IF NOT EXISTS approach_cameras (
  approach_camera_id serial PRIMARY KEY,
  camera_code       text UNIQUE NOT NULL,
  junction_code     text NOT NULL,
  from_road         text,
  location          geometry(Point, 4326) NOT NULL,
  heading_degrees   int,
  travel_degrees    int);
TRUNCATE cameras, roads, plates, camera_links, sightings, blacklist_entries,
         alerts, camera_metrics_5m, traffic_metrics_5m, approach_cameras RESTART IDENTITY CASCADE;

